// TOPICALS SEAM — one place that groups lib/topicals-bank.ts into subjects
// and chapters for the public /topicals pages. Counts are computed from the
// bank at module scope; nothing is hardcoded and nothing is invented.
//
// The bank itself is generated by scripts/ingest-topicals.mjs (see its header
// for the honesty rules). This file never edits question text.

import { TOPICALS_BANK, type TopicalsQuestion } from './topicals-bank';

export type { TopicalsQuestion };

export function topicSlug(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}

export type TopicChapter = {
  /** URL-safe slug, e.g. "acellular-life". */
  slug: string;
  /** Display title, e.g. "Acellular Life". */
  title: string;
  count: number;
};

export type TopicSubject = {
  /** URL-safe slug, e.g. "biology". */
  slug: string;
  name: string;
  icon: string;
  count: number;
  chapters: TopicChapter[];
};

function buildSubjects(): TopicSubject[] {
  const order = [
    { name: 'Biology', icon: '🧬' },
    { name: 'Chemistry', icon: '⚗️' },
    { name: 'Physics', icon: '⚛️' },
  ];
  const subjects: TopicSubject[] = [];
  for (const s of order) {
    const rows = TOPICALS_BANK.filter((q) => q.subject === s.name);
    const chapterMap = new Map<string, number>();
    for (const q of rows) {
      chapterMap.set(q.chapter, (chapterMap.get(q.chapter) ?? 0) + 1);
    }
    const chapters: TopicChapter[] = [...chapterMap.entries()]
      .map(([title, count]) => ({ slug: topicSlug(title), title, count }))
      .sort((a, b) => b.count - a.count || a.title.localeCompare(b.title));
    subjects.push({
      slug: topicSlug(s.name),
      name: s.name,
      icon: s.icon,
      count: rows.length,
      chapters,
    });
  }
  return subjects;
}

export const TOPICALS_SUBJECTS: TopicSubject[] = buildSubjects();

export const TOPICALS_TOTAL: number = TOPICALS_BANK.length;

export const TOPICALS_CHAPTER_COUNT: number = TOPICALS_SUBJECTS.reduce(
  (n, s) => n + s.chapters.length,
  0
);

export function topicalSubject(slug: string): TopicSubject | null {
  return TOPICALS_SUBJECTS.find((s) => s.slug === slug) ?? null;
}

/** Chapter by subject+chapter slug; null for an unknown pair (caller 404s). */
export function topicalChapter(
  subjectSlug: string,
  chapterSlug: string
): { subject: TopicSubject; chapter: TopicChapter; questions: TopicalsQuestion[] } | null {
  const subject = topicalSubject(subjectSlug);
  if (!subject) return null;
  const chapter = subject.chapters.find((c) => c.slug === chapterSlug);
  if (!chapter) return null;
  const questions = TOPICALS_BANK.filter(
    (q) => q.subject === subject.name && q.chapter === chapter.title
  );
  return { subject, chapter, questions };
}
